    ) -> Result<Vec<EventProjection>, EventServiceError> {
        let access = self
            .read_access(actor_user_id, is_superadmin, calendar_id)
            .await?;
        let mut projected: Vec<_> = EventRepository::new(self.pool.clone())
            .events_in_range(calendar_id, range.clone())
