/// Issue a `REPORT` request and return the status and body text.
async fn report_request(
    app: Router,
    uri: &str,
    username: &str,
    password: &str,
    body: &str,
) -> (StatusCode, String) {
    let request = Request::builder()
        .method(Method::from_bytes(b"REPORT").unwrap())
        .uri(uri)
        .header(header::AUTHORIZATION, basic_header(username, password))
        .header(header::CONTENT_TYPE, "application/xml; charset=utf-8")
        .body(Body::from(body.to_owned()))
        .unwrap();
    let response = app.oneshot(request).await.unwrap();
    let status = response.status();
    let body = response.into_body().collect().await.unwrap().to_bytes();
    (status, String::from_utf8_lossy(&body).into_owned())
}

fn calendar_query_xml(start: &str, end: &str) -> String {
    format!(
        r#"<?xml version="1.0" encoding="utf-8" ?>
<C:calendar-query xmlns:D="DAV:" xmlns:C="urn:ietf:params:xml:ns:calendarserver/">
  <D:prop>
    <D:getetag/>
    <D:getcontenttype/>
    <C:calendar-data/>
  </D:prop>
  <C:filter>
    <C:time-range start="{start}" end="{end}"/>
  </C:filter>
</C:calendar-query>"#
    )
}

fn multiget_xml(href: &str) -> String {
    format!(
        r#"<?xml version="1.0" encoding="utf-8" ?>
<C:calendar-multiget xmlns:D="DAV:" xmlns:C="urn:ietf:params:xml:ns:calendarserver/">
  <D:prop>
    <D:getetag/>
    <D:getcontenttype/>
    <C:calendar-data/>
  </D:prop>
  <D:href>{href}</D:href>
</C:calendar-multiget>"#
    )
}

